insert into public.conteudos (id,categoria,titulo,minutos,autor,corpo,destaque,publicado,publicado_em) values ($t$rotina-visual$t$,$t$artigo$t$,$t$Rotina visual: como começar$t$,4,$t$Equipe teia$t$,$t$[{"p":"Uma rotina visual mostra, com fotos ou desenhos, o que vai acontecer ao longo do dia. Ela ajuda a criança a prever os próximos passos e costuma diminuir a ansiedade nas transições."},{"h":"Por onde começar"},{"ul":["Escolha só 3 ou 4 momentos do dia, como acordar, comer, terapia e dormir.","Use fotos reais da casa e dos objetos dela, ou desenhos simples.","Deixe em um lugar baixo, que ela alcance e veja.","Retire a figura ou vire o cartão quando a etapa terminar."]},{"p":"Comece pequeno e aumente aos poucos. Se algo mudar no dia, avise e mostre a mudança no quadro. Converse com a terapeuta ocupacional ou a psicóloga de vocês para adaptar ao jeito do seu filho."}]$t$::jsonb,true,true,now() - interval '0 days') on conflict (id) do nothing;
insert into public.conteudos (id,categoria,titulo,minutos,autor,corpo,destaque,publicado,publicado_em) values ($t$consulta$t$,$t$dica$t$,$t$Como preparar a consulta e não esquecer nada$t$,3,$t$Equipe teia$t$,$t$[{"p":"Consultas costumam ser curtas e cheias de informação. Um pouco de preparo ajuda a aproveitar melhor o tempo."},{"h":"Antes"},{"ul":["Anote 3 perguntas principais.","Leve laudos e receitas recentes. No app, eles ficam na pasta Documentos.","Registre o que mudou desde a última vez: sono, humor, comportamento e conquistas."]},{"h":"Depois"},{"p":"Escreva o que foi combinado e peça por escrito o que for mudar na medicação ou nas terapias. Fotografe a nova receita no app para atualizar a rotina."}]$t$::jsonb,false,true,now() - interval '1 days') on conflict (id) do nothing;
insert into public.conteudos (id,categoria,titulo,minutos,autor,corpo,destaque,publicado,publicado_em) values ($t$ciptea$t$,$t$direitos$t$,$t$Carteira CIPTEA: o que é e para que serve$t$,4,$t$Equipe teia$t$,$t$[{"p":"A Carteira de Identificação da Pessoa com Transtorno do Espectro Autista (CIPTEA) foi criada pela Lei 13.977/2020, conhecida como Lei Romeo Mion. Ela ajuda a comprovar o diagnóstico e a pedir atendimento prioritário em serviços públicos e privados."},{"h":"Como pedir"},{"p":"As regras de emissão variam por estado e município. Em geral, é preciso apresentar documentos da pessoa, comprovante de residência e laudo médico. Procure o órgão de assistência social ou de direitos da pessoa com deficiência da sua cidade para saber o passo a passo."},{"p":"A Lei 12.764/2012, a Lei Berenice Piedade, garante à pessoa com autismo os direitos das pessoas com deficiência. Este texto é informativo e não substitui orientação jurídica."}]$t$::jsonb,false,true,now() - interval '2 days') on conflict (id) do nothing;
insert into public.conteudos (id,categoria,titulo,minutos,autor,corpo,destaque,publicado,publicado_em) values ($t$cuidar$t$,$t$artigo$t$,$t$Cuidando de quem cuida: pequenas pausas$t$,3,$t$Equipe teia$t$,$t$[{"p":"Mães e cuidadores costumam colocar a própria saúde por último. Cuidar de si também é parte do cuidado com o seu filho."},{"ul":["Combine com alguém da rede um horário fixo na semana só seu.","Peça ajuda de forma específica: buscar na escola, ficar uma hora, fazer uma compra.","Mantenha um compromisso seu na agenda, como consulta, caminhada ou encontro com uma amiga.","Se o cansaço ou a tristeza durarem muito, procure um profissional de saúde mental."]},{"p":"Você não precisa dar conta de tudo sozinha."}]$t$::jsonb,false,true,now() - interval '3 days') on conflict (id) do nothing;
insert into public.conteudos (id,categoria,titulo,minutos,autor,corpo,destaque,publicado,publicado_em) values ($t$seletividade$t$,$t$artigo$t$,$t$Seletividade alimentar: por onde começar$t$,4,$t$Equipe teia$t$,$t$[{"p":"É comum que crianças com autismo aceitem poucos alimentos por causa de texturas, cheiros e cores. Forçar costuma aumentar a recusa."},{"ul":["Apresente o alimento novo ao lado de um que ela já aceita, sem pressão.","Deixe tocar, cheirar e brincar com a comida.","Mantenha horários regulares e um ambiente calmo.","Evite substituir refeições por leite ou lanches o dia todo."]},{"p":"Se a lista de alimentos for muito curta ou houver perda de peso, procure o pediatra, um nutricionista ou uma fonoaudióloga com experiência em alimentação."}]$t$::jsonb,false,true,now() - interval '4 days') on conflict (id) do nothing;
